package io.github.jdubois.bootui.engine.databaseadvisor;

import io.github.jdubois.bootui.core.dto.DatabaseAdvisorRuleResultDto;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * A single-column, auto-generated (identity/{@code AUTO_INCREMENT}/serial) primary key typed narrower than a
 * plain 32-bit integer — {@code TINYINT} or {@code SMALLINT}/{@code INT2} — which exhausts after a small,
 * fixed number of rows regardless of how full the table is today.
 *
 * <p>This is a structural, design-time risk check, not a usage-based one: it fires the moment the schema is
 * created, before the {@code TINYINT}/{@code SMALLINT} counter has consumed any meaningful fraction of its
 * own tiny range, which is exactly when the type is cheapest to widen. {@code DB-PG-002}/{@code DB-MYSQL-003}
 * (and {@code DB-ORACLE-003}) separately catch a sequence/{@code AUTO_INCREMENT} counter that is already
 * close to its column's actual maximum, at any width.</p>
 *
 * <p>Deliberately narrow in scope: only a single-column primary key that the database itself auto-generates
 * is checked — a manually-assigned {@code TINYINT} key on a small, bounded reference/lookup table (a set of
 * five status codes that will never grow) is a legitimate, common design and not a defect, and a composite
 * primary key's individual column widths are a different, less clear-cut question this rule does not guess
 * at. {@code MEDIUM} (not {@code MEDIUM}/{@code HIGH} usage-based) because it is a review prompt about future
 * risk, not evidence of an active problem today.</p>
 */
final class NarrowAutoGeneratedPrimaryKeyRule extends AbstractDatabaseAdvisorRule {

    private static final Set<String> TINYINT_NAMES = Set.of("tinyint");
    private static final Set<String> SMALLINT_NAMES = Set.of("smallint", "int2", "smallserial");

    NarrowAutoGeneratedPrimaryKeyRule() {
        super(new DatabaseAdvisorRuleDefinition(
                "DB-SCHEMA-007",
                "Narrow auto-generated primary key",
                DatabaseAdvisorCategory.SCHEMA,
                DatabaseAdvisorRuleSupport.MEDIUM,
                "Detects a single-column, auto-generated (IS_AUTOINCREMENT/identity/serial) primary key typed "
                        + "TINYINT or SMALLINT/INT2, regardless of how many rows the table currently has.",
                "Widen the primary key column (and every foreign key referencing it) to INTEGER or BIGINT "
                        + "before the table grows, in the same migration that creates it if possible. A TINYINT "
                        + "surrogate key exhausts after at most 255 rows ever inserted, and a SMALLINT after at "
                        + "most 65,535 — widening later requires rewriting every referencing foreign key too.",
                "https://www.postgresql.org/docs/current/datatype-numeric.html"));
    }

    @Override
    DatabaseAdvisorRuleResultDto evaluateRule(DatabaseAdvisorContext context) {
        List<String> details = new ArrayList<>();
        for (SchemaSnapshot schema : context.availableSchemas()) {
            for (TableModel table : DatabaseAdvisorContext.analyzableTables(schema)) {
                if (!table.metadata().primaryKeyRead() || !table.metadata().columnsRead()) {
                    continue;
                }
                checkTable(schema, table, details);
            }
        }
        return violation(details);
    }

    private void checkTable(SchemaSnapshot schema, TableModel table, List<String> details) {
        List<String> primaryKeyColumns = table.primaryKeyColumns();
        if (primaryKeyColumns.size() != 1) {
            return;
        }
        ColumnModel column = table.column(primaryKeyColumns.get(0));
        if (column == null || !column.autoIncrement()) {
            return;
        }
        BigInteger capacity = capacity(column);
        if (capacity == null) {
            return;
        }
        details.add(schema.dataSourceName() + ": " + table.qualifiedName() + "." + column.name() + " ("
                + column.describeType() + ") is an auto-generated primary key that can hold at most " + capacity
                + " distinct values.");
    }

    /** The maximum values a narrow (TINYINT/SMALLINT-class) column can hold, or {@code null} otherwise. */
    private BigInteger capacity(ColumnModel column) {
        String normalized = normalizeTypeName(column.typeName());
        if (normalized.isEmpty()) {
            return null;
        }
        boolean unsigned = column.unsigned();
        if (TINYINT_NAMES.contains(normalized)) {
            return unsigned ? BigInteger.valueOf(255) : BigInteger.valueOf(127);
        }
        if (SMALLINT_NAMES.contains(normalized)) {
            return unsigned ? BigInteger.valueOf(65_535) : BigInteger.valueOf(32_767);
        }
        return null;
    }

    private String normalizeTypeName(String typeName) {
        if (typeName == null) {
            return "";
        }
        String normalized = typeName.toLowerCase(Locale.ROOT).trim();
        int parenthesis = normalized.indexOf('(');
        if (parenthesis >= 0) {
            normalized = normalized.substring(0, parenthesis).trim();
        }
        return normalized.replace(" unsigned", "").replace(" zerofill", "").trim();
    }
}
